window.AVL_SOURCES = [{"label": "提交版（OJ 用）", "file": "mod11.py", "lang": "py", "stripped": "import sys\n\ndef make_reader():\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n            buf.extend(line.split())\n        return buf.pop(0)\n\n    def has_buffered():\n        return len(buf) > 0\n\n    return nxt, has_buffered\n\ndef is_uint(s):\n    if not s:\n        return False\n    for ch in s:\n        if ch < \"0\" or ch > \"9\":\n            return False\n    return True\n\ndef mod11(s):\n    diff = 0\n    sign = 1\n    for i in range(len(s) - 1, -1, -1):\n        diff += sign * (ord(s[i]) - 48)\n        sign = -sign\n    return diff % 11\n\ndef main():\n    nxt, has_buffered = make_reader()\n\n    tok = nxt()\n    if tok is None:\n        return\n    if not is_uint(tok):\n        print(\"[!] invalid T: \" + repr(tok), file=sys.stderr)\n        return\n    t = int(tok)\n\n    answers = []\n    for case in range(1, t + 1):\n        s = nxt()\n        if s is None:\n            print(\"[!] EOF while reading n of case \" + str(case)\n                  + \" (expected \" + str(t) + \" case(s))\", file=sys.stderr)\n            return\n        if not is_uint(s):\n            print(\"[!] case \" + str(case)\n                  + \": n must be a decimal integer, got \" + repr(s),\n                  file=sys.stderr)\n            return\n\n        answers.append(mod11(s))\n\n    if answers:\n        out = []\n        for a in answers:\n            out.append(str(a))\n        sys.stdout.write(\"\\n\".join(out) + \"\\n\")\n        sys.stdout.flush()\n\n    if has_buffered():\n        print(\"[!] extra token(s) on the last line after \" + str(t)\n              + \" case(s) -- 第 1 行写的是 T 组数，请核对这一行是否多余\",\n              file=sys.stderr)\n\nif __name__ == \"__main__\":\n    main()\n", "original": "# -*- coding: utf-8 -*-\n#\n# 求 n 被 11 除的余数\n# ===================\n# Input:  第 1 行一个整数 T (T < 20)；随后 T 行，每行一个十进制正整数 n (长度 <= 80)\n# Output: 每行一个整数 —— n mod 11 的余数，取值 0..10\n#\n# 原理\n# ----\n# 10 = 11 - 1 ≡ -1 (mod 11)，故 10^k ≡ (-1)^k (mod 11)。\n# 把 n 按位展开 n = Σ d_k · 10^k，逐项取模得\n#\n#       n ≡ Σ d_k · (-1)^k   (mod 11)\n#\n# 也就是说：把各位从**个位起**编号 k = 0, 1, 2, ...，\n# 偶数号的（个位、百位、万位…… 即中文习惯的\"奇数位\"）取 +，\n# 奇数号的（十位、千位…… 即\"偶数位\"）取 -，\n# 得到的交替和 diff 与 n 同余，于是  n mod 11 = diff mod 11。\n#\n# 为什么要按字符串算\n# ------------------\n# n 最多 80 位，远超 C 的 long long（约 19 位十进制），\n# 所以从头到尾都按**字符串逐位**处理，绝不先 int(n)。\n# （Python 有任意精度整数，本地写 int(n) % 11 也照样对，\n#   但那份代码搬到 C 语言就整个塌掉 —— 这题考的就是不进大整数库。）\n#\n# 输入输出（仓库铁律）\n# -------------------\n#   * 一律 readline() 逐行读 —— 终端 / PyCharm / OJ 三种环境都对。\n#     既不用 sys.stdin.read()（终端里要读到 EOF 才返回，用户以为卡死），\n#     也不用 isatty() 分流（PyCharm 运行窗口的 stdin 不是真 tty，会退回那条死路）。\n#   * stdout 只留答案，一个余数一行、行尾带换行；\n#     任何错误走 stderr 并带 \"[!]\" 前缀。\n#   * 非法输入（非数字、数据不足）宁可中止也不打伪答案。\n\nimport sys\n\n\ndef make_reader():\n    \"\"\"返回 (nxt, has_buffered)。\n\n    nxt           —— 每次吐一个空白分隔的 token，取完返回 None。\n                     逐行 readline()，三种环境通用：OJ 上 EOF 时返回空串，\n                     缓冲区自然空掉、循环结束，结果与 read() 一致。\n    has_buffered  —— 缓冲区里是否还压着没消费的 token。\n                     **只看内存，不读 stdin** —— 一读就会在终端里阻塞。\n    \"\"\"\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:                  # EOF / Ctrl+Z\n                return None\n            buf.extend(line.split())\n        return buf.pop(0)\n\n    def has_buffered():\n        return len(buf) > 0\n\n    return nxt, has_buffered\n\n\ndef is_uint(s):\n    \"\"\"s 是否为纯十进制数字串（允许前导零，拒绝空串 / 正负号 / 小数点）。\n\n    先校验再计算，是为了守住\"宁可中止也不错答\"：\n    若把 '12abc' 直接丢进 mod11()，逐位取数会凭空算出个像模像样的错答案。\n    \"\"\"\n    if not s:\n        return False\n    for ch in s:\n        if ch < \"0\" or ch > \"9\":\n            return False\n    return True\n\n\ndef mod11(s):\n    \"\"\"返回 int(s) mod 11。\n\n    前置条件：s 是非空纯数字串（由 is_uint 校验，本函数不再检查）。\n\n    从个位 s[-1] 往高位扫，符号 +1 / -1 交替，累加出交替和 diff。\n    diff 可能为负，但 Python 的 % 对负数返回非负余数（-1 % 11 == 10），\n    正是题目要的结果，不必额外补正 —— 注意 C 版必须手工补，见 mod11.c。\n    \"\"\"\n    diff = 0\n    sign = 1                              # 个位（k = 0）取 +\n    for i in range(len(s) - 1, -1, -1):\n        diff += sign * (ord(s[i]) - 48)   # ord(ch) - 48 即该位的数值\n        sign = -sign\n    return diff % 11\n\n\ndef main():\n    nxt, has_buffered = make_reader()\n\n    tok = nxt()\n    if tok is None:                       # 连 T 都没有：空输入，安静返回\n        return\n    if not is_uint(tok):\n        print(\"[!] invalid T: \" + repr(tok), file=sys.stderr)\n        return\n    t = int(tok)\n\n    answers = []\n    for case in range(1, t + 1):\n        s = nxt()\n        if s is None:\n            print(\"[!] EOF while reading n of case \" + str(case)\n                  + \" (expected \" + str(t) + \" case(s))\", file=sys.stderr)\n            return\n        if not is_uint(s):\n            print(\"[!] case \" + str(case)\n                  + \": n must be a decimal integer, got \" + repr(s),\n                  file=sys.stderr)\n            return\n\n        answers.append(mod11(s))\n\n    # ★ 全部读完后**一次性**输出。\n    # 在终端里手敲时，答案会集中出现在输入之后，而不是和输入一行行穿插 ——\n    # 手敲 4 行数据，屏幕上是「4 行输入 + 3 行答案」，而不是 输入/答案/输入/答案。\n    # 对 OJ 没有任何影响：判题只看 stdout 的内容，不看写出的时机。\n    # 中途出错（EOF / 非法 n）时会提前 return，根本走不到这里，\n    # stdout 保持为空 —— 也就不会出现\"只打了半截答案\"的情况。\n    if answers:\n        out = []\n        for a in answers:\n            out.append(str(a))\n        sys.stdout.write(\"\\n\".join(out) + \"\\n\")   # 行尾必须有换行（铁律 4）\n        sys.stdout.flush()\n\n    # 读完 T 组后，若**同一行**还压着没消费的 token，多半说明判题格式不是\n    # \"给定 T 组\"。这里刻意只看缓冲区、**绝不再读一行**：\n    # 再调一次 nxt() 就会阻塞在 readline() 上，终端里表现为\"答案已经打完、\n    # 程序却不结束\"，与铁律 1 是同族的坑（用户以为卡死，得去按 Ctrl+Z）。\n    # 代价是\"下一行还有多余数据\"这种情况探测不到了 —— 宁可少提示，\n    # 也不能让终端里的人对着一个不结束的程序发呆。\n    if has_buffered():\n        print(\"[!] extra token(s) on the last line after \" + str(t)\n              + \" case(s) -- 第 1 行写的是 T 组数，请核对这一行是否多余\",\n              file=sys.stderr)\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"label": "详细版（本地学习）", "file": "mod11_detailed.py", "lang": "py", "stripped": "import sys\n\ndef mod11_alternating(s):\n    plus = 0\n    minus = 0\n    n = len(s)\n    for k in range(n):\n        d = ord(s[-1 - k]) - 48\n        if k % 2 == 0:\n            plus += d\n        else:\n            minus += d\n    diff = plus - minus\n    return plus, minus, diff, diff % 11\n\ndef mod11_horner(s):\n    r = 0\n    for ch in s:\n        r = (r * 10 + (ord(ch) - 48)) % 11\n    return r\n\ndef mod11_bigint(s):\n    return int(s) % 11\n\ndef show_digits(s, chunk=18):\n    w = 4\n    n = len(s)\n    order = list(range(n - 1, -1, -1))\n\n    for start in range(0, n, chunk):\n        part = order[start:start + chunk]\n        row_k = \"\".join(str(k).rjust(w) for k in part)\n        row_d = \"\".join(s[-1 - k].rjust(w) for k in part)\n        row_g = \"\".join((\"+\" if k % 2 == 0 else \"-\").rjust(w) for k in part)\n        row_c = \"\".join(((\"+\" if k % 2 == 0 else \"-\") + s[-1 - k]).rjust(w)\n                        for k in part)\n        print(\"    位号 k\" + row_k)\n        print(\"    数字 d\" + row_d)\n        print(\"    符号  \" + row_g)\n        print(\"    贡献  \" + row_c)\n        print(\"\")\n\ndef show_pow10_cycle(kmax=12):\n    mods = []\n    signs = []\n    p = 1\n    for _ in range(kmax):\n        mods.append(str(p))\n        signs.append(\"1\" if p == 1 else \"-1\")\n        p = (p * 10) % 11\n    print(\"    10^k mod 11  (k=0,1,2,...): \" + \" \".join(mods))\n    print(\"    记成带符号的形式          : \" + \" \".join(signs))\n    print(\"    只有 1 和 -1 两种取值，于是第 k 位的权重 = (-1)^k，逐位交替。\")\n\ndef show_horner(s, limit=30):\n    steps = []\n    r = 0\n    for i in range(len(s)):\n        r = (r * 10 + (ord(s[i]) - 48)) % 11\n        steps.append(r)\n    if not steps:\n        return 0\n    if len(steps) <= limit:\n        print(\"    中间余数: \" + \" \".join(str(x) for x in steps))\n    else:\n        head = \" \".join(str(x) for x in steps[:8])\n        tail = \" \".join(str(x) for x in steps[-4:])\n        print(\"    中间余数: \" + head + \" ... \" + tail\n              + \"    (共 \" + str(len(steps)) + \" 步，中间省略)\")\n    return steps[-1]\n\ndef make_reader():\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:\n                return None\n            buf.extend(line.split())\n        return buf.pop(0)\n\n    def has_buffered():\n        return len(buf) > 0\n\n    return nxt, has_buffered\n\ndef is_uint(s):\n    if not s:\n        return False\n    for ch in s:\n        if ch < \"0\" or ch > \"9\":\n            return False\n    return True\n\ndef main():\n    nxt, has_buffered = make_reader()\n\n    tok = nxt()\n    if tok is None:\n        return\n    if not is_uint(tok):\n        print(\"[!] invalid T: \" + repr(tok), file=sys.stderr)\n        return\n    t = int(tok)\n\n    answers = []\n\n    for case in range(1, t + 1):\n        s = nxt()\n        if s is None:\n            print(\"[!] EOF while reading n of case \" + str(case)\n                  + \" (expected \" + str(t) + \" case(s))\", file=sys.stderr)\n            return\n        if not is_uint(s):\n            print(\"[!] case \" + str(case)\n                  + \": n must be a decimal integer, got \" + repr(s),\n                  file=sys.stderr)\n            return\n\n        print(\"\")\n        print(\"=\" * 62)\n        print(\"Case \" + str(case) + \"    n = \" + s + \"    (\" + str(len(s)) + \" 位)\")\n        print(\"=\" * 62)\n\n        print(\"\")\n        print(\"[1] 逐位摊开  (k 从个位起算；k 偶取 +，k 奇取 -)\")\n        show_digits(s)\n\n        plus, minus, diff, rem = mod11_alternating(s)\n        print(\"[2] 交替和\")\n        print(\"    个位起偶数号位之和 plus  = \" + str(plus))\n        print(\"    个位起奇数号位之和 minus = \" + str(minus))\n        print(\"    diff = plus - minus = \" + str(plus) + \" - \" + str(minus)\n              + \" = \" + str(diff))\n        print(\"    n mod 11 = diff mod 11 = \" + str(diff) + \" mod 11 = \" + str(rem))\n\n        print(\"\")\n        print(\"[3] 符号为什么会逐位交替：\")\n        show_pow10_cycle()\n\n        print(\"\")\n        print(\"[4] Sum check 交叉验证（三套独立算法必须给出同一个数）\")\n        h = show_horner(s)\n        big = mod11_bigint(s)\n        ok = (h == rem) and (big == rem)\n        print(\"    交替和法        -> \" + str(rem))\n        print(\"    Horner 逐位取模 -> \" + str(h))\n        print(\"    Python 大整数   -> \" + str(big) + \"    (任意精度，仅本地可用)\")\n        print(\"    Sum check: \" + (\"三法一致 -> OK\" if ok\n                                   else \"分歧 -> MISMATCH  <-- 有 bug！\"))\n        if not ok:\n            print(\"[!] Sum check FAILED for n = \" + s, file=sys.stderr)\n\n        print(\"\")\n        print(\"  >>> 答案: \" + str(rem))\n\n        answers.append(rem)\n        sys.stdout.flush()\n\n    if has_buffered():\n        print(\"[!] extra token(s) on the last line after \" + str(t)\n              + \" case(s) -- 第 1 行写的是 T 组数，请核对这一行是否多余\",\n              file=sys.stderr)\n\n    if answers:\n        print(\"\")\n        print(\"=\" * 62)\n        print(\"OJ 标准格式输出（提交请用 mod11.py，本文件仅供本地学习）\")\n        print(\"=\" * 62)\n        for a in answers:\n            print(a)\n        sys.stdout.flush()\n\nif __name__ == \"__main__\":\n    main()\n", "original": "# -*- coding: utf-8 -*-\n\"\"\"\nn 被 11 除的余数 —— 详细版\n==========================\n⚠️ 仅本地学习用 —— 请勿提交本文件到 OJ！它输出完整推导过程，判题必 WA。\n   真正要提交的是同目录下的 mod11.py（只输出余数，一行一组）。\n\n本文件对每组输入做三件事：\n\n  [1] 把 n 的每一位摊开成表：位号 k / 数字 d / 权重符号 / 该位贡献\n  [2] 用**交替和**算出 diff，再 diff % 11 得到余数\n  [3] Sum check 自校 —— 换两套完全独立的算法重算，三者必须一致：\n        * Horner 逐位取模  r = (r * 10 + d) % 11   （通用法，与 11 的特殊性无关）\n        * Python 原生大整数 int(n) % 11            （任意精度，本地才有，C 语言做不到）\n\n交替和为什么成立\n----------------\n10 = 11 - 1 ≡ -1 (mod 11)  =>  10^k ≡ (-1)^k (mod 11)\n\n把 n 按位展开 n = Σ d_k · 10^k（k 从个位起编号 0），逐项取模：\n\n      n ≡ Σ d_k · (-1)^k   (mod 11)\n\n于是个位、百位、万位……（k 为偶数）取 +，十位、千位……（k 为奇数）取 -，\n交替和 diff 与 n 同余，n mod 11 == diff mod 11。\n\nInput:\n  第 1 行 T；随后 T 行，每行一个十进制正整数 n（长度 <= 80）\nOutput:\n  每组一段推导过程；文件末尾再按 OJ 标准格式输出一遍纯答案，便于逐字比对。\n\"\"\"\n\nimport sys\n\n\n# ---------------------------------------------------------------- 三套算法\n\ndef mod11_alternating(s):\n    \"\"\"交替和法（本文件主角）。返回 (plus, minus, diff, rem)。\n\n    plus  = 个位起偶数号位（k = 0,2,4,...）数字之和\n    minus = 个位起奇数号位（k = 1,3,5,...）数字之和\n    diff  = plus - minus，与 n 同余\n    rem   = diff % 11\n\n    前置条件：s 是非空纯数字串。\n    \"\"\"\n    plus = 0\n    minus = 0\n    n = len(s)\n    for k in range(n):\n        d = ord(s[-1 - k]) - 48           # 从个位起第 k 位的数值\n        if k % 2 == 0:\n            plus += d\n        else:\n            minus += d\n    diff = plus - minus\n    return plus, minus, diff, diff % 11\n\n\ndef mod11_horner(s):\n    \"\"\"Horner 逐位取模：从最高位起 r = (r * 10 + d) % 11。\n\n    通用做法，不依赖 11 的任何特殊性，可用来给交替和当\"第二意见\"。\n    \"\"\"\n    r = 0\n    for ch in s:\n        r = (r * 10 + (ord(ch) - 48)) % 11\n    return r\n\n\ndef mod11_bigint(s):\n    \"\"\"直接交给 Python 的任意精度整数：int(n) % 11。\n\n    只有 Python 能这么写（C 的 long long 装不下 19 位以上）。\n    本地拿它当\"裁判\"，确认前两套手写算法没算错。\n    \"\"\"\n    return int(s) % 11\n\n\n# ---------------------------------------------------------------- 展示部分\n\ndef show_digits(s, chunk=18):\n    \"\"\"把各位从高位到低位分块打印：位号 k / 数字 d / 符号 / 该位贡献。\n\n    k 从个位起算：最高位是 k = len(s)-1，个位是 k = 0。\n    符号只看 k 的奇偶 —— k 偶取 +，k 奇取 -，与数字本身无关。\n    \"\"\"\n    w = 4\n    n = len(s)\n    order = list(range(n - 1, -1, -1))    # 高位 -> 低位，符合阅读习惯\n\n    for start in range(0, n, chunk):\n        part = order[start:start + chunk]\n        row_k = \"\".join(str(k).rjust(w) for k in part)\n        row_d = \"\".join(s[-1 - k].rjust(w) for k in part)\n        row_g = \"\".join((\"+\" if k % 2 == 0 else \"-\").rjust(w) for k in part)\n        row_c = \"\".join(((\"+\" if k % 2 == 0 else \"-\") + s[-1 - k]).rjust(w)\n                        for k in part)\n        print(\"    位号 k\" + row_k)\n        print(\"    数字 d\" + row_d)\n        print(\"    符号  \" + row_g)\n        print(\"    贡献  \" + row_c)\n        print(\"\")\n\n\ndef show_pow10_cycle(kmax=12):\n    \"\"\"展示 10^k mod 11 的循环，解释\"为什么相邻位符号相反\"。\"\"\"\n    mods = []\n    signs = []\n    p = 1\n    for _ in range(kmax):\n        mods.append(str(p))\n        signs.append(\"1\" if p == 1 else \"-1\")\n        p = (p * 10) % 11                 # 10^0=1 -> 10^1=10 -> 10^2=1 -> ...\n    print(\"    10^k mod 11  (k=0,1,2,...): \" + \" \".join(mods))\n    print(\"    记成带符号的形式          : \" + \" \".join(signs))\n    print(\"    只有 1 和 -1 两种取值，于是第 k 位的权重 = (-1)^k，逐位交替。\")\n\n\ndef show_horner(s, limit=30):\n    \"\"\"展示 Horner 的中间余数序列；太长就只展示头尾。返回最终余数。\"\"\"\n    steps = []\n    r = 0\n    for i in range(len(s)):\n        r = (r * 10 + (ord(s[i]) - 48)) % 11\n        steps.append(r)\n    if not steps:\n        return 0\n    if len(steps) <= limit:\n        print(\"    中间余数: \" + \" \".join(str(x) for x in steps))\n    else:\n        head = \" \".join(str(x) for x in steps[:8])\n        tail = \" \".join(str(x) for x in steps[-4:])\n        print(\"    中间余数: \" + head + \" ... \" + tail\n              + \"    (共 \" + str(len(steps)) + \" 步，中间省略)\")\n    return steps[-1]\n\n\n# ---------------------------------------------------------------- 输入输出\n\ndef make_reader():\n    \"\"\"返回 (nxt, has_buffered)。\n\n    nxt          —— 逐 token 读；取完返回 None。统一 readline()，三环境通用。\n    has_buffered —— 缓冲区里是否还压着没消费的 token（只看内存，不读 stdin）。\n    \"\"\"\n    buf = []\n\n    def nxt():\n        while not buf:\n            line = sys.stdin.readline()\n            if not line:                  # EOF / Ctrl+Z\n                return None\n            buf.extend(line.split())\n        return buf.pop(0)\n\n    def has_buffered():\n        return len(buf) > 0\n\n    return nxt, has_buffered\n\n\ndef is_uint(s):\n    \"\"\"s 是否为纯十进制数字串（允许前导零，拒绝空串 / 正负号 / 小数点）。\"\"\"\n    if not s:\n        return False\n    for ch in s:\n        if ch < \"0\" or ch > \"9\":\n            return False\n    return True\n\n\ndef main():\n    nxt, has_buffered = make_reader()\n\n    tok = nxt()\n    if tok is None:\n        return\n    if not is_uint(tok):\n        print(\"[!] invalid T: \" + repr(tok), file=sys.stderr)\n        return\n    t = int(tok)\n\n    answers = []\n\n    for case in range(1, t + 1):\n        s = nxt()\n        if s is None:\n            print(\"[!] EOF while reading n of case \" + str(case)\n                  + \" (expected \" + str(t) + \" case(s))\", file=sys.stderr)\n            return\n        if not is_uint(s):\n            print(\"[!] case \" + str(case)\n                  + \": n must be a decimal integer, got \" + repr(s),\n                  file=sys.stderr)\n            return\n\n        print(\"\")\n        print(\"=\" * 62)\n        print(\"Case \" + str(case) + \"    n = \" + s + \"    (\" + str(len(s)) + \" 位)\")\n        print(\"=\" * 62)\n\n        print(\"\")\n        print(\"[1] 逐位摊开  (k 从个位起算；k 偶取 +，k 奇取 -)\")\n        show_digits(s)\n\n        plus, minus, diff, rem = mod11_alternating(s)\n        print(\"[2] 交替和\")\n        print(\"    个位起偶数号位之和 plus  = \" + str(plus))\n        print(\"    个位起奇数号位之和 minus = \" + str(minus))\n        print(\"    diff = plus - minus = \" + str(plus) + \" - \" + str(minus)\n              + \" = \" + str(diff))\n        print(\"    n mod 11 = diff mod 11 = \" + str(diff) + \" mod 11 = \" + str(rem))\n\n        print(\"\")\n        print(\"[3] 符号为什么会逐位交替：\")\n        show_pow10_cycle()\n\n        print(\"\")\n        print(\"[4] Sum check 交叉验证（三套独立算法必须给出同一个数）\")\n        h = show_horner(s)\n        big = mod11_bigint(s)\n        ok = (h == rem) and (big == rem)\n        print(\"    交替和法        -> \" + str(rem))\n        print(\"    Horner 逐位取模 -> \" + str(h))\n        print(\"    Python 大整数   -> \" + str(big) + \"    (任意精度，仅本地可用)\")\n        print(\"    Sum check: \" + (\"三法一致 -> OK\" if ok\n                                   else \"分歧 -> MISMATCH  <-- 有 bug！\"))\n        if not ok:\n            print(\"[!] Sum check FAILED for n = \" + s, file=sys.stderr)\n\n        print(\"\")\n        print(\"  >>> 答案: \" + str(rem))\n\n        answers.append(rem)\n        sys.stdout.flush()\n\n    # 同 mod11.py：只看缓冲区、绝不再读一行 ——\n    # 再读一次就会在终端里阻塞，表现为\"过程都打完了、程序却不结束\"。\n    if has_buffered():\n        print(\"[!] extra token(s) on the last line after \" + str(t)\n              + \" case(s) -- 第 1 行写的是 T 组数，请核对这一行是否多余\",\n              file=sys.stderr)\n\n    # 末尾按 OJ 标准格式再打一遍，便于和 mod11.py 的输出逐字比对\n    if answers:\n        print(\"\")\n        print(\"=\" * 62)\n        print(\"OJ 标准格式输出（提交请用 mod11.py，本文件仅供本地学习）\")\n        print(\"=\" * 62)\n        for a in answers:\n            print(a)\n        sys.stdout.flush()\n\n\nif __name__ == \"__main__\":\n    main()\n"}, {"label": "C 实现", "file": "mod11.c", "lang": "c", "stripped": "#include <stdio.h>\n\n#define MAXLEN 96\n#define MAXCASE 1001\n\nstatic char line[MAXLEN + 8];\nstatic char *cursor = NULL;\nstatic int  ans[MAXCASE];\n\n\nstatic int read_line(void) {\n    int i = 0;\n\n    for (;;) {\n        int c = fgetc(stdin);\n\n        if (c == EOF) {\n            if (i == 0) {\n                return 0;\n            }\n            line[i] = '\\0';\n            return 1;\n        }\n        if (c == '\\n') {\n            line[i] = '\\0';\n            return 1;\n        }\n        if (c == '\\0') {\n            line[i] = '\\0';\n            return -2;\n        }\n        if (i >= (int)sizeof(line) - 1) {\n            line[i] = '\\0';\n            return -1;\n        }\n        line[i] = (char)c;\n        i++;\n    }\n}\n\n\nstatic int next_token(char *out, int cap) {\n    for (;;) {\n        if (cursor == NULL || *cursor == '\\0') {\n            int r = read_line();\n            if (r <= 0) {\n                return r;\n            }\n            cursor = line;\n        }\n        while (*cursor == ' ' || *cursor == '\\t' ||\n               *cursor == '\\r' || *cursor == '\\n') {\n            cursor++;\n        }\n        if (*cursor == '\\0') {\n            continue;\n        }\n\n        int n = 0;\n        while (*cursor != '\\0' && *cursor != ' ' && *cursor != '\\t' &&\n               *cursor != '\\r' && *cursor != '\\n') {\n            if (n >= cap - 1) {\n                return -3;\n            }\n            out[n++] = *cursor++;\n        }\n        out[n] = '\\0';\n        return 1;\n    }\n}\n\n\nstatic const char *why_neg(int st) {\n    if (st == -1) {\n        return \"line too long\";\n    }\n    if (st == -2) {\n        return \"line contains a NUL byte\";\n    }\n    return \"token too long\";\n}\n\n\nstatic int is_uint(const char *s) {\n    if (*s == '\\0') {\n        return 0;\n    }\n    for (; *s; s++) {\n        if (*s < '0' || *s > '9') {\n            return 0;\n        }\n    }\n    return 1;\n}\n\nint main(void) {\n    char tok[MAXLEN];\n    int st = next_token(tok, MAXLEN);\n\n    if (st == 0) {\n        return 0;\n    }\n    if (st < 0) {\n        fprintf(stderr, \"[!] T: %s (max %d chars)\\n\", why_neg(st), MAXLEN - 1);\n        return 0;\n    }\n    if (!is_uint(tok)) {\n        fprintf(stderr, \"[!] invalid T: \\\"%s\\\"\\n\", tok);\n        return 0;\n    }\n\n\n    long t = 0;\n    long n_case = 0;\n    const char *p = tok;\n    for (; *p; p++) {\n        t = t * 10 + (*p - '0');\n        if (t > (long)(MAXCASE - 1)) {\n            fprintf(stderr, \"[!] T too large: \\\"%s\\\"\\n\", tok);\n            return 0;\n        }\n    }\n\n    for (long c = 1; c <= t; c++) {\n        st = next_token(tok, MAXLEN);\n        if (st == 0) {\n            fprintf(stderr, \"[!] EOF while reading n of case %ld \"\n                            \"(expected %ld case(s))\\n\", c, t);\n            return 0;\n        }\n        if (st < 0) {\n            fprintf(stderr, \"[!] case %ld: %s (max %d chars)\\n\",\n                    c, why_neg(st), MAXLEN - 1);\n            return 0;\n        }\n        if (!is_uint(tok)) {\n            fprintf(stderr, \"[!] case %ld: n must be a decimal integer, got \\\"%s\\\"\\n\",\n                    c, tok);\n            return 0;\n        }\n\n        int len = 0;\n        while (tok[len] != '\\0') {\n            len++;\n        }\n\n        int diff = 0;\n        int sign = 1;\n        for (int i = len - 1; i >= 0; i--) {\n            diff += sign * (tok[i] - '0');\n            sign = -sign;\n        }\n\n\n        int r = diff % 11;\n        if (r < 0) {\n            r += 11;\n        }\n\n        ans[n_case] = r;\n        n_case++;\n    }\n\n\n    for (long i = 0; i < n_case; i++) {\n        printf(\"%d\\n\", ans[i]);\n    }\n    fflush(stdout);\n\n\n    if (cursor != NULL) {\n        while (*cursor == ' ' || *cursor == '\\t' || *cursor == '\\r') {\n            cursor++;\n        }\n        if (*cursor != '\\0' && *cursor != '\\n') {\n            fprintf(stderr, \"[!] extra token(s) on the last line after \"\n                            \"%ld case(s); please re-check the judge format\\n\", t);\n        }\n    }\n\n    return 0;\n}\n", "original": "/*\n * n 被 11 除的余数 (C implementation)\n * ====================================\n * 原理：10 = 11 - 1 ≡ -1 (mod 11)，故 10^k ≡ (-1)^k (mod 11)。\n *       把 n 按位展开 n = Σ d_k · 10^k（k 从个位起编号 0），得\n *\n *           n ≡ Σ d_k · (-1)^k   (mod 11)\n *\n *       即个位、百位、万位……（k 为偶）取 +，十位、千位……（k 为奇）取 -，\n *       交替和 diff 与 n 同余，答案就是 diff mod 11。\n *\n * n 最多 80 位，远超 long long（约 19 位十进制）——\n * 所以全程按**字符串逐位**处理，一次整数转换都不做。\n *\n * ⚠️ 本题在 C 侧最容易漏的一步：C99 的 % 对负数返回负值（-1 % 11 == -1），\n *    而 Python 的 % 直接返回 10。所以 C 版必须手工补正：\n *        if (r < 0) r += 11;\n *    锚定用例 n = \"10\"（交替和 = -1）专门抓这个，忘了补正就输出 -1。\n *\n * Input:  第 1 行一个整数 T (T < 20)；随后 T 行，每行一个十进制正整数 n (≤ 80 位)\n * Output: 每行一个整数 —— n mod 11，取值 0..10\n *\n * Compile: gcc -O2 -o mod11 mod11.c\n * Run:     ./mod11 < input.txt\n *   需要 C99 以上（循环内声明变量、语句后再声明等）；gcc / clang 默认就是\n *   gnu17，直接编译即可。若判题机强行 -std=c89 会报编译错误（本仓库其它\n *   题目的 .c 亦然）。\n *\n * ⚠️⚠️ 本机没有任何 C 编译器（gcc / clang / tcc / cl / zig 全无），\n *      本文件**从未编译、从未运行验证过**。逻辑与 mod11.py 逐行对应，\n *      但请在使用前自行编译核对。\n */\n\n#include <stdio.h>\n\n#define MAXLEN 96              /* 题面 80 位，留足余量；超长会报错而不是截断 */\n#define MAXCASE 1001           /* T 的上限（题面 T < 20，1000 已是 50 倍余量） */\n\nstatic char line[MAXLEN + 8];\nstatic char *cursor = NULL;     /* 本行读到的位置；NULL 表示还没读任何一行 */\nstatic int  ans[MAXCASE];       /* 攒答案，读完所有组再一次性输出 */\n\n/*\n * 读入一行到 line（换行符丢弃，末尾补 '\\0'）。\n *   返回  1 = 成功\n *         0 = EOF（一个字符都没读到）\n *        -1 = 这一行太长，超出缓冲区\n *        -2 = 这一行里含 NUL 字节\n *\n * ★ 为什么不用 fgets —— 这是本文件最容易踩的地方。\n *\n *   fgets(buf, n, fp) 读满 n-1 个字符就**立刻返回，且不会告诉你它截断了**。\n *   把残缺的行当完整行继续用，就可能切出一个\"长度合法、内容错误\"的\n *   token，算出像模像样的错答案。而想事后补救也不容易：\n *\n *     - 用 strlen 数\"读了多少\" —— 会被输入里的 '\\0' 骗过（i 偏小）；\n *     - 用 feof(fp) 判\"是不是到文件尾了\" —— **同样不成立**：\n *       fgets 凑满字符数就直接返回了，那一刻它根本没去探文件尾，\n *       EOF 标志还是 0。于是\"缓冲满 + 末字符非换行\"时 feof 恒为 0，\n *       会把\"文件最后一行刚好占满缓冲且没有换行符\"的合法输入\n *       误判成截断（真实 CRT 实测如此，glibc 的 _IO_getline_info\n *       也是 n 减到 0 就退出循环、不再探流）。\n *\n *   干脆自己用 fgetc 逐字符读：读了多少个字符由我们自己数（i），\n *   换行 / EOF / 溢出 / NUL 四种情况各走各的分支，没有猜测空间。\n *\n *   （曾经的反面教材：line 缓冲 104 字节、token 上限 95 字符时，\n *     \"token 起始列偏移 >= 9 且整行 > 103 字符\"会让 token 在 103 字符处\n *     被切断却仍判为成功 —— 例如 `1` + 换行 + 24 个空格 + 80 个 9，\n *     会输出 9，而真值是 0。）\n */\nstatic int read_line(void) {\n    int i = 0;\n\n    for (;;) {\n        int c = fgetc(stdin);\n\n        if (c == EOF) {\n            if (i == 0) {\n                return 0;                      /* 一个字符都没读到 = 流已结束 */\n            }\n            line[i] = '\\0';\n            return 1;                          /* 文件最后一行没有换行符 */\n        }\n        if (c == '\\n') {\n            line[i] = '\\0';                    /* 换行符丢掉，不留给 token */\n            return 1;\n        }\n        if (c == '\\0') {\n            line[i] = '\\0';\n            return -2;                         /* 文本输入不该出现 NUL 字节 */\n        }\n        if (i >= (int)sizeof(line) - 1) {\n            line[i] = '\\0';\n            return -1;                         /* 缓冲区满了还有后续 => 行太长 */\n        }\n        line[i] = (char)c;\n        i++;\n    }\n}\n\n/*\n * 取一个空白分隔的 token 放进 out（容量 cap）。\n *   返回  1 = 成功\n *         0 = EOF\n *        -1 = 整行太长（read_line 判定）\n *        -2 = 整行含 NUL 字节（read_line 判定）\n *        -3 = token 本身太长\n *\n * 为什么不用 scanf(\"%79s\")：超长 token 会被**静默截断**成 79 个字符，\n * 而截断结果往往还是纯数字，于是算出一个看着很像样的错答案。\n * 宁可控告也不能错答（CLAUDE.md 铁律 6 / 陷阱 13）。\n */\nstatic int next_token(char *out, int cap) {\n    for (;;) {\n        if (cursor == NULL || *cursor == '\\0') {\n            int r = read_line();\n            if (r <= 0) {\n                return r;              /* 0 = EOF；负值 = 行太长/含 NUL */\n            }\n            cursor = line;\n        }\n        while (*cursor == ' ' || *cursor == '\\t' ||\n               *cursor == '\\r' || *cursor == '\\n') {\n            cursor++;\n        }\n        if (*cursor == '\\0') {\n            continue;                              /* 空行：接着读下一行 */\n        }\n\n        int n = 0;\n        while (*cursor != '\\0' && *cursor != ' ' && *cursor != '\\t' &&\n               *cursor != '\\r' && *cursor != '\\n') {\n            if (n >= cap - 1) {\n                return -3;                         /* token 超长 */\n            }\n            out[n++] = *cursor++;\n        }\n        out[n] = '\\0';\n        return 1;\n    }\n}\n\n/* 把 next_token 的负返回值翻译成给人看的短语，现场排障时能一眼看出是哪种超限 */\nstatic const char *why_neg(int st) {\n    if (st == -1) {\n        return \"line too long\";\n    }\n    if (st == -2) {\n        return \"line contains a NUL byte\";\n    }\n    return \"token too long\";\n}\n\n/* 纯十进制数字串？（允许前导零，拒绝空串 / 正负号 / 小数点 / 字母） */\nstatic int is_uint(const char *s) {\n    if (*s == '\\0') {\n        return 0;\n    }\n    for (; *s; s++) {\n        if (*s < '0' || *s > '9') {\n            return 0;\n        }\n    }\n    return 1;\n}\n\nint main(void) {\n    char tok[MAXLEN];\n    int st = next_token(tok, MAXLEN);\n\n    if (st == 0) {\n        return 0;                                  /* 空输入：安静退出 */\n    }\n    if (st < 0) {\n        fprintf(stderr, \"[!] T: %s (max %d chars)\\n\", why_neg(st), MAXLEN - 1);\n        return 0;\n    }\n    if (!is_uint(tok)) {\n        fprintf(stderr, \"[!] invalid T: \\\"%s\\\"\\n\", tok);\n        return 0;\n    }\n\n    /* 题面 T < 20；这里仍防一手病态输入，别让它把循环拖死。\n       检查放在累加**之后** —— 否则最后一位刚好把 t 顶过阈值时会漏网：\n       阈值 1000 时，\"1009\" 会被放前的写法放过（前三位只到 100，\n       放前写法在乘之前就查完了；第四位才变成 1009，正好没人查）。\n       上限取 MAXCASE-1，正好保证 ans 不会越界；t 在报错前最大约 10009，\n       离 long 的上限还远，不会溢出。 */\n    long t = 0;\n    long n_case = 0;\n    const char *p = tok;\n    for (; *p; p++) {\n        t = t * 10 + (*p - '0');\n        if (t > (long)(MAXCASE - 1)) {\n            fprintf(stderr, \"[!] T too large: \\\"%s\\\"\\n\", tok);\n            return 0;\n        }\n    }\n\n    for (long c = 1; c <= t; c++) {\n        st = next_token(tok, MAXLEN);\n        if (st == 0) {\n            fprintf(stderr, \"[!] EOF while reading n of case %ld \"\n                            \"(expected %ld case(s))\\n\", c, t);\n            return 0;\n        }\n        if (st < 0) {\n            fprintf(stderr, \"[!] case %ld: %s (max %d chars)\\n\",\n                    c, why_neg(st), MAXLEN - 1);\n            return 0;\n        }\n        if (!is_uint(tok)) {\n            fprintf(stderr, \"[!] case %ld: n must be a decimal integer, got \\\"%s\\\"\\n\",\n                    c, tok);\n            return 0;\n        }\n\n        int len = 0;\n        while (tok[len] != '\\0') {\n            len++;\n        }\n\n        int diff = 0;\n        int sign = 1;                              /* 个位（k = 0）取 + */\n        for (int i = len - 1; i >= 0; i--) {\n            diff += sign * (tok[i] - '0');\n            sign = -sign;\n        }\n        /* 80 位全 9 时 |diff| ≤ 720，int 绰绰有余 */\n\n        int r = diff % 11;\n        if (r < 0) {\n            r += 11;       /* ★ C99 负数取模补正；Python 不需要，C 必须做 */\n        }\n\n        ans[n_case] = r;               /* 先攒着，读完所有组再一起输出 */\n        n_case++;\n    }\n\n    /* ★ 全部读完后**一次性**输出 —— 与 mod11.py 保持一致。\n       终端里手敲时答案会集中在输入之后，而不是和输入一行行穿插；\n       对 OJ 没有影响（判题只看 stdout 的内容，不看写出的时机）。\n       T 已限制在 MAXCASE-1 以内，所以 ans 不会越界。 */\n    for (long i = 0; i < n_case; i++) {\n        printf(\"%d\\n\", ans[i]);\n    }\n    fflush(stdout);\n\n    /* 读完 T 组后，若当前行还压着 token，提示判题格式可能不是\"给定 T 组\"。\n       这里刻意只看 cursor，**绝不再调用 next_token()** —— 那会再读一次 stdin\n       （read_line 里的 fgetc 会等输入），终端里就阻塞住了，表现为\n       \"答案已经打完、程序却不结束\"（与 Python 版同一考虑，见铁律 1）。 */\n    if (cursor != NULL) {\n        while (*cursor == ' ' || *cursor == '\\t' || *cursor == '\\r') {\n            cursor++;\n        }\n        if (*cursor != '\\0' && *cursor != '\\n') {\n            fprintf(stderr, \"[!] extra token(s) on the last line after \"\n                            \"%ld case(s); please re-check the judge format\\n\", t);\n        }\n    }\n\n    return 0;\n}\n"}, {"label": "验证脚本 verify_mod11.py", "file": "verify_mod11.py", "lang": "py", "stripped": "import ast\nimport importlib.util\nimport os\nimport random\nimport subprocess\nimport sys\nimport threading\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"mod11.py\")\nDETAILED = os.path.join(HERE, \"mod11_detailed.py\")\n\ndef _load(path, modname):\n    spec = importlib.util.spec_from_file_location(modname, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\nmini = _load(MINI, \"mod11_under_test\")\ndetailed = _load(DETAILED, \"mod11_detailed_under_test\")\n\nsolve = mini.mod11\nis_uint = mini.is_uint\nalt = detailed.mod11_alternating\nhorner = detailed.mod11_horner\nbigint = detailed.mod11_bigint\n\nANCHORS = [\n\n    (\"78\", 1, \"题面样例 1\"),\n    (\"70906\", 0, \"题面样例 2（交替和 = 22）\"),\n    (\"781020569876102789\", 2, \"题面样例 3（18 位，交替和 = 2）\"),\n    (\"0\", 0, \"0 —— 题面说正整数，留个底\"),\n    (\"1\", 1, \"最小一位正整数\"),\n    (\"9\", 9, \"一位数上界\"),\n    (\"10\", 10, \"★负 diff 锚定：diff = 0-1 = -1，不补正会输出 -1\"),\n    (\"91\", 3, \"★负 diff 锚定之二：diff = -8\"),\n    (\"19\", 8, \"与 91 镜像（同数字、反奇偶位）\"),\n    (\"11\", 0, \"11 的倍数\"),\n    (\"121\", 0, \"★11 的倍数（11^2）\"),\n    (\"12\", 1, \"★方向锚定：按字符从左起取符号会得 10\"),\n    (\"0012\", 1, \"★前导零锚定：前导零不改数值也不改余数\"),\n    (\"0121\", 0, \"前导零 + 11 的倍数\"),\n    (\"3\" * 80, 0, \"★题面最大长度 80 位：80 位全 3 的交替和恰为 0\"),\n    (\"9\" * 80, 0, \"★80 位全 9\"),\n    (\"1\" + \"0\" * 79, 10, \"★80 位 10 的幂：diff = -1，负余数补正的另一道卡\"),\n]\n\ndef check_anchors():\n    fails = []\n    for s, want, why in ANCHORS:\n        got = solve(s)\n        if got != want:\n            fails.append(f\"锚定【{why}】n={s[:24]}... got {got}, want {want}\")\n\n    for bad in (\"\", \"abc\", \"12abc\", \"-5\", \"1.5\", \" 12\", \"٣\"):\n        if is_uint(bad):\n            fails.append(f\"is_uint({bad!r}) 应为 False\")\n    for good in (\"0\", \"00\", \"0121\", \"9\" * 80):\n        if not is_uint(good):\n            fails.append(f\"is_uint({good[:12]!r}) 应为 True\")\n    return fails\n\ndef check_exhaustive():\n    fails = []\n    total = 0\n    for width in range(1, 5):\n        for v in range(10 ** width):\n            s = str(v).zfill(width)\n            total += 1\n            got = solve(s)\n            want = v % 11\n            if got != want:\n                fails.append(f\"穷举 n={s} got {got}, want {want}\")\n    return total, fails\n\ndef check_random(rnd, rounds=20000):\n    fails = []\n    total = 0\n\n    for _ in range(rounds):\n        L = rnd.randint(1, 80)\n        s = \"\".join(rnd.choice(\"0123456789\") for _ in range(L))\n        total += 1\n        got = solve(s)\n        want = int(s) % 11\n        if got != want:\n            fails.append(f\"随机 n={s} got {got}, want {want}\")\n\n    for L in range(1, 81):\n        for s in (\"9\" * L, \"1\" + \"0\" * (L - 1), \"0\" * L):\n            total += 1\n            got = solve(s)\n            want = int(s) % 11\n            if got != want:\n                fails.append(f\"专项 n={s[:24]}... (len {L}) got {got}, want {want}\")\n\n    for _ in range(2000):\n        k = rnd.randint(1, 10 ** 79 // 11)\n        s = str(11 * k)\n        if len(s) > 80:\n            continue\n        total += 1\n        got = solve(s)\n        if got != 0:\n            fails.append(f\"11 的倍数 n={s} got {got}, want 0\")\n\n    return total, fails\n\ndef check_detailed(rnd, rounds=4000):\n    fails = []\n    total = 0\n\n    cases = [s for s, _w, _why in ANCHORS]\n    for _ in range(rounds):\n        L = rnd.randint(1, 80)\n        cases.append(\"\".join(rnd.choice(\"0123456789\") for _ in range(L)))\n\n    for s in cases:\n        total += 1\n        plus, minus, diff, rem = alt(s)\n        want = int(s) % 11\n        if plus - minus != diff:\n            fails.append(f\"detailed n={s}: plus-minus={plus - minus} != diff={diff}\")\n        elif rem != want:\n            fails.append(f\"detailed 交替和 n={s}: got {rem}, want {want}\")\n        elif horner(s) != want:\n            fails.append(f\"detailed Horner n={s}: got {horner(s)}, want {want}\")\n        elif bigint(s) != want:\n            fails.append(f\"detailed 大整数 n={s}: got {bigint(s)}, want {want}\")\n        elif solve(s) != want:\n            fails.append(f\"提交版 vs 期望 n={s}: got {solve(s)}, want {want}\")\n    return total, fails\n\ndef run_mini(text):\n    p = subprocess.run([sys.executable, MINI], input=text,\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                       encoding=\"utf-8\", errors=\"replace\")\n    return p.stdout or \"\", p.stderr or \"\", p.returncode\n\ndef check_e2e():\n    fails = []\n    total = 0\n\n    clean_cases = [\n        (\"题面样例\", \"3\\n78\\n70906\\n781020569876102789\\n\", \"1\\n0\\n2\\n\"),\n        (\"单组\", \"1\\n5\\n\", \"5\\n\"),\n        (\"T=0（不输出任何东西）\", \"0\\n\", \"\"),\n        (\"空输入\", \"\", \"\"),\n        (\"T 与 n 同行（宽容解析）\", \"2 78 91\\n\", \"1\\n3\\n\"),\n        (\"CRLF 行尾（Windows 文本）\", \"2\\r\\n78\\r\\n91\\r\\n\", \"1\\n3\\n\"),\n        (\"夹空行 / 前后空行\", \"\\n\\n1\\n\\n78\\n\\n\", \"1\\n\"),\n        (\"80 位 + 前导零\", \"2\\n\" + \"1\" + \"0\" * 79 + \"\\n0012\\n\", \"10\\n1\\n\"),\n        (\"每组之间无空行（标准）\", \"4\\n10\\n19\\n91\\n121\\n\", \"10\\n8\\n3\\n0\\n\"),\n        (\"下一行有多余数据（只算 T 组，不再读、不阻塞）\", \"1\\n78\\n99\\n\", \"1\\n\"),\n    ]\n    for why, text, want in clean_cases:\n        total += 1\n        out, err, _rc = run_mini(text)\n        if out != want:\n            fails.append(f\"e2e【{why}】stdout={out!r}, want {want!r}\")\n        if err != \"\":\n            fails.append(f\"e2e【{why}】stderr 应为空，实为 {err!r}\")\n\n    bad_cases = [\n        (\"非法 n\", \"1\\nhello\\n\", \"\"),\n        (\"数字混字母\", \"1\\n12abc\\n\", \"\"),\n        (\"带负号（第 2 组才出错，前 1 组也不能漏出去）\", \"2\\n78\\n-91\\n\", \"\"),\n        (\"非法 T\", \"abc\\n78\\n\", \"\"),\n        (\"缺数据（T=3 只给 2 个）\", \"3\\n78\\n91\\n\", \"\"),\n        (\"同一行里多出 token（缓冲区里看得见）\", \"1 78 99\\n\", \"1\\n\"),\n    ]\n    for why, text, want in bad_cases:\n        total += 1\n        out, err, _rc = run_mini(text)\n        if out != want:\n            fails.append(f\"e2e【{why}】stdout={out!r}, want {want!r}\")\n        if not err.startswith(\"[!]\"):\n            fails.append(f\"e2e【{why}】stderr 应以 [!] 开头，实为 {err!r}\")\n\n    return total, fails\n\ndef check_streaming(timeout=5.0):\n    p = subprocess.Popen([sys.executable, MINI], stdin=subprocess.PIPE,\n                         stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                         encoding=\"utf-8\", errors=\"replace\")\n    got = []\n\n    def rd():\n        got.append(p.stdout.readline())\n\n    try:\n        p.stdin.write(\"1\\n78\\n\")\n        p.stdin.flush()\n        th = threading.Thread(target=rd)\n        th.daemon = True\n        th.start()\n        th.join(timeout)\n    except Exception as e:\n        got.append(\"<EXC %s>\" % e)\n    finally:\n        try:\n            p.kill()\n            p.stdin.close()\n            p.stdout.close()\n            p.stderr.close()\n        except Exception:\n            pass\n\n    if not got:\n\n        return (\"%.0f 秒内没吐出第一行 —— 疑似退回 read()（铁律 1：\"\n                \"终端里表现就是「敲完数据毫无反应」）\" % timeout)\n    if got[0].strip() != \"1\":\n        return \"第一行是 %r，期望 '1'\" % got[0]\n    return None\n\ndef check_no_trailing_block(timeout=5.0):\n    p = subprocess.Popen([sys.executable, MINI], stdin=subprocess.PIPE,\n                         stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                         encoding=\"utf-8\", errors=\"replace\")\n    try:\n        p.stdin.write(\"1\\n78\\n\")\n        p.stdin.flush()\n    except Exception as e:\n        return \"写入 stdin 失败: %s\" % e\n\n    try:\n        p.wait(timeout=timeout)\n    except subprocess.TimeoutExpired:\n        p.kill()\n        for h in (p.stdin, p.stdout, p.stderr):\n            try:\n                h.close()\n            except Exception:\n                pass\n        return (\"喂完 T 组后 %.0f 秒仍未退出 —— 收尾又去读 stdin 了\"\n                \"（终端里就是「打完不结束」）\" % timeout)\n\n    out = p.stdout.read() or \"\"\n    for h in (p.stdin, p.stdout, p.stderr):\n        try:\n            h.close()\n        except Exception:\n            pass\n    if out != \"1\\n\":\n        return \"stdout = %r，期望 '1\\\\n'\" % out\n    return None\n\ndef check_detailed_e2e(timeout=5.0):\n    p = subprocess.Popen([sys.executable, DETAILED], stdin=subprocess.PIPE,\n                         stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                         encoding=\"utf-8\", errors=\"replace\")\n    try:\n        p.stdin.write(\"2\\n78\\n10\\n\")\n        p.stdin.flush()\n    except Exception as e:\n        return \"写入 stdin 失败: %s\" % e\n\n    try:\n        p.wait(timeout=timeout)\n    except subprocess.TimeoutExpired:\n        p.kill()\n        for h in (p.stdin, p.stdout, p.stderr):\n            try:\n                h.close()\n            except Exception:\n                pass\n        return \"喂完 T 组后 %.0f 秒仍未退出 —— 收尾又去读 stdin 了\" % timeout\n\n    out = p.stdout.read() or \"\"\n    err = p.stderr.read() or \"\"\n    for h in (p.stdin, p.stdout, p.stderr):\n        try:\n            h.close()\n        except Exception:\n            pass\n\n    if err != \"\":\n        return \"stderr 非空: %r\" % err\n    tail = out.rstrip(\"\\n\").split(\"\\n\")[-2:]\n    if tail != [\"1\", \"10\"]:\n        return \"末尾的标准格式输出为 %r，期望 ['1', '10']\" % tail\n    return None\n\ndef ast_scan(path):\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        src = f.read()\n    tree = ast.parse(src, path)\n\n    bad = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.JoinedStr):\n            bad.append((\"f-string\", node.lineno))\n        elif isinstance(node, ast.NamedExpr):\n            bad.append((\"海象运算符 :=\", node.lineno))\n        elif isinstance(node, ast.Nonlocal):\n            bad.append((\"nonlocal\", node.lineno))\n        elif isinstance(node, ast.AnnAssign):\n            bad.append((\"变量类型注解\", node.lineno))\n        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            for a in list(node.args.args) + list(node.args.kwonlyargs):\n                if getattr(a, \"annotation\", None) is not None:\n                    bad.append((\"参数类型注解\", node.lineno))\n            if node.returns is not None:\n                bad.append((\"返回类型注解\", node.lineno))\n        elif isinstance(node, ast.Call):\n            f = node.func\n            if isinstance(f, ast.Name) and f.id == \"input\":\n                bad.append((\"input()\", node.lineno))\n            if isinstance(f, ast.Attribute) and f.attr == \"buffer\":\n                bad.append((\"sys.stdin.buffer\", node.lineno))\n    return bad\n\ndef main():\n    rnd = random.Random(20260927)\n    failures = []\n\n    failures += check_anchors()\n\n    exh_total, f = check_exhaustive()\n    failures += f\n\n    rnd_total, f = check_random(rnd)\n    failures += f\n\n    det_total, f = check_detailed(rnd)\n    failures += f\n\n    e2e_total, f = check_e2e()\n    failures += f\n\n    err = check_streaming()\n    if err:\n        failures.append(\"流式（终端行为）: \" + err)\n\n    err = check_no_trailing_block()\n    if err:\n        failures.append(\"收尾不阻塞: \" + err)\n\n    err = check_detailed_e2e()\n    if err:\n        failures.append(\"详细版端到端: \" + err)\n\n    for path in (MINI, DETAILED):\n        for what, lineno in ast_scan(path):\n            failures.append(f\"AST {os.path.basename(path)}:{lineno} 含禁用语法 {what}\")\n\n    if failures:\n        print(\"FAIL: %d 处\" % len(failures))\n        for x in failures[:5]:\n            print(\"  - \" + x)\n        return 1\n\n    print(\"OK: anchors %d | exhaustive %d | random %d | detailed 3-way agree %d | \"\n          \"stdout clean %d | streaming ok | no-block ok | detailed e2e ok | \"\n          \"AST clean (2 files)\"\n          % (len(ANCHORS), exh_total, rnd_total, det_total, e2e_total))\n    return 0\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n", "original": "#!/usr/bin/env python3\n\"\"\"\n11 的余数 —— 自动对拍 / 自查脚本\n=================================\n\n全部检查通过才打印 OK，任一失败打印前 5 条并 exit 1。\n\n检查项：\n\n  0. 锚定用例          题面样例 + 专门钉死典型错法的边界\n  1. 全穷举对拍        1~4 位十进制数（零填充，共 11110 个）逐一与 int(n) % 11 对拍\n  2. 随机长数对拍      随机 1~80 位 20000 个 + 全 9 / 10^k / 11 的倍数专项\n  3. detailed 三法一致 交替和 / Horner / Python 大整数，且与提交版逐例相同\n  4. 端到端 stdout     真的起子进程跑 mod11.py：stdout 逐字节比对，\n                       并断言正常情形下 stderr 必须为空（铁律 3、4）\n  5. 流式（终端行为）  stdin 喂完第一组**不关闭**，5 秒内必须吐出第一行答案。\n                       这正是铁律 1 的坑：退回 sys.stdin.read() 就会一直等到 EOF，\n                       终端里表现为\"敲完数据毫无反应\"\n  6. 收尾不阻塞        喂完 T 组后进程必须自己退出，不得再读一次 stdin ——\n                       否则终端里就是\"答案打完了、程序却不结束\"\n  7. AST 语法检查      mod11.py / mod11_detailed.py 不得含 OJ 老 Python 不认的语法\n                       （f-string / buffer / nonlocal / 类型注解 / 海象 / input）\n                       注意：**不能用 grep** —— readline 含 read 子串会误报\n\n被测对象是**真正提交的文件** mod11.py / mod11_detailed.py，不是内部副本 ——\n避免\"验证脚本和实际代码各改各的\"这类漂移（CLAUDE.md 陷阱 10）。\n\n锚定用例（专门钉死最典型的几种错法）\n------------------------------------\n\n  * \"10\" -> 10   交替和 diff = 0-1 = **-1**（负）。\n                 C 版忘了 `if (r < 0) r += 11;` 会输出 -1；\n                 Python 版若写成 abs(diff) % 11 会输出 1。\n  * \"91\" -> 3    diff = -8，负余数补正的第二道卡（差 3 到 -11）。\n  * \"19\" -> 8    与 \"91\" 镜像：同样的两个数字、相反的奇偶位置。\n  * \"12\" -> 1    **方向锚定**：必须\"从个位起编号\"。若按字符串从左起取符号，\n                 会得 10 —— 前导零用例 \"0012\" 同样能抓到这个错。\n  * \"121\" -> 0   11 的倍数（11^2）。\n  * 80 位全 9 -> 0，'1'+79 个 0 -> 10   题面最大长度（80 位）两端。\n\"\"\"\n\nimport ast\nimport importlib.util\nimport os\nimport random\nimport subprocess\nimport sys\nimport threading\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nMINI = os.path.join(HERE, \"mod11.py\")\nDETAILED = os.path.join(HERE, \"mod11_detailed.py\")\n\n\ndef _load(path, modname):\n    \"\"\"载入待测文件本体（不是副本）。\"\"\"\n    spec = importlib.util.spec_from_file_location(modname, path)\n    mod = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(mod)\n    return mod\n\n\nmini = _load(MINI, \"mod11_under_test\")\ndetailed = _load(DETAILED, \"mod11_detailed_under_test\")\n\nsolve = mini.mod11\nis_uint = mini.is_uint\nalt = detailed.mod11_alternating\nhorner = detailed.mod11_horner\nbigint = detailed.mod11_bigint\n\n\n# ------------------------------------------------------------------ 期望值来源\n# 下面每个 want 都用 `python -c \"print(int(s) % 11)\"` 实跑核对过，\n# 不是手算的（CLAUDE.md 陷阱 19：验证脚本自己的期望值也会写错）。\nANCHORS = [\n    # (n, 期望余数, 说明)\n    (\"78\", 1, \"题面样例 1\"),\n    (\"70906\", 0, \"题面样例 2（交替和 = 22）\"),\n    (\"781020569876102789\", 2, \"题面样例 3（18 位，交替和 = 2）\"),\n    (\"0\", 0, \"0 —— 题面说正整数，留个底\"),\n    (\"1\", 1, \"最小一位正整数\"),\n    (\"9\", 9, \"一位数上界\"),\n    (\"10\", 10, \"★负 diff 锚定：diff = 0-1 = -1，不补正会输出 -1\"),\n    (\"91\", 3, \"★负 diff 锚定之二：diff = -8\"),\n    (\"19\", 8, \"与 91 镜像（同数字、反奇偶位）\"),\n    (\"11\", 0, \"11 的倍数\"),\n    (\"121\", 0, \"★11 的倍数（11^2）\"),\n    (\"12\", 1, \"★方向锚定：按字符从左起取符号会得 10\"),\n    (\"0012\", 1, \"★前导零锚定：前导零不改数值也不改余数\"),\n    (\"0121\", 0, \"前导零 + 11 的倍数\"),\n    (\"3\" * 80, 0, \"★题面最大长度 80 位：80 位全 3 的交替和恰为 0\"),\n    (\"9\" * 80, 0, \"★80 位全 9\"),\n    (\"1\" + \"0\" * 79, 10, \"★80 位 10 的幂：diff = -1，负余数补正的另一道卡\"),\n]\n\n\ndef check_anchors():\n    fails = []\n    for s, want, why in ANCHORS:\n        got = solve(s)\n        if got != want:\n            fails.append(f\"锚定【{why}】n={s[:24]}... got {got}, want {want}\")\n    # 顺手确认校验器本身：这几个必须被判为非法\n    for bad in (\"\", \"abc\", \"12abc\", \"-5\", \"1.5\", \" 12\", \"٣\"):\n        if is_uint(bad):\n            fails.append(f\"is_uint({bad!r}) 应为 False\")\n    for good in (\"0\", \"00\", \"0121\", \"9\" * 80):\n        if not is_uint(good):\n            fails.append(f\"is_uint({good[:12]!r}) 应为 True\")\n    return fails\n\n\ndef check_exhaustive():\n    \"\"\"1~4 位全穷举（零填充，顺带扫前导零）。\"\"\"\n    fails = []\n    total = 0\n    for width in range(1, 5):\n        for v in range(10 ** width):\n            s = str(v).zfill(width)\n            total += 1\n            got = solve(s)\n            want = v % 11                       # 零填充与数值同余，直接用 v\n            if got != want:\n                fails.append(f\"穷举 n={s} got {got}, want {want}\")\n    return total, fails\n\n\ndef check_random(rnd, rounds=20000):\n    \"\"\"随机 1~80 位 + 极端专项。\"\"\"\n    fails = []\n    total = 0\n\n    for _ in range(rounds):\n        L = rnd.randint(1, 80)\n        s = \"\".join(rnd.choice(\"0123456789\") for _ in range(L))\n        total += 1\n        got = solve(s)\n        want = int(s) % 11\n        if got != want:\n            fails.append(f\"随机 n={s} got {got}, want {want}\")\n\n    # 专项：全 9 / 10 的幂 / 全 0，长度扫满 1..80\n    for L in range(1, 81):\n        for s in (\"9\" * L, \"1\" + \"0\" * (L - 1), \"0\" * L):\n            total += 1\n            got = solve(s)\n            want = int(s) % 11\n            if got != want:\n                fails.append(f\"专项 n={s[:24]}... (len {L}) got {got}, want {want}\")\n\n    # 专项：11 的倍数（余数必须是 0）\n    for _ in range(2000):\n        k = rnd.randint(1, 10 ** 79 // 11)\n        s = str(11 * k)\n        if len(s) > 80:\n            continue\n        total += 1\n        got = solve(s)\n        if got != 0:\n            fails.append(f\"11 的倍数 n={s} got {got}, want 0\")\n\n    return total, fails\n\n\ndef check_detailed(rnd, rounds=4000):\n    \"\"\"详细版三套算法互校，且必须与提交版逐例相同。\"\"\"\n    fails = []\n    total = 0\n\n    cases = [s for s, _w, _why in ANCHORS]\n    for _ in range(rounds):\n        L = rnd.randint(1, 80)\n        cases.append(\"\".join(rnd.choice(\"0123456789\") for _ in range(L)))\n\n    for s in cases:\n        total += 1\n        plus, minus, diff, rem = alt(s)\n        want = int(s) % 11\n        if plus - minus != diff:\n            fails.append(f\"detailed n={s}: plus-minus={plus - minus} != diff={diff}\")\n        elif rem != want:\n            fails.append(f\"detailed 交替和 n={s}: got {rem}, want {want}\")\n        elif horner(s) != want:\n            fails.append(f\"detailed Horner n={s}: got {horner(s)}, want {want}\")\n        elif bigint(s) != want:\n            fails.append(f\"detailed 大整数 n={s}: got {bigint(s)}, want {want}\")\n        elif solve(s) != want:\n            fails.append(f\"提交版 vs 期望 n={s}: got {solve(s)}, want {want}\")\n    return total, fails\n\n\n# ------------------------------------------------------------------ 端到端\n\ndef run_mini(text):\n    \"\"\"起子进程跑 mod11.py（管道 stdin，等价于 OJ 环境）。\n\n    ★ 显式指定 utf-8 + errors=\"replace\" 来解码。\n    子进程写出的中文 stderr 可能按本机 locale 编码（Windows 下常是 GBK），\n    交给 subprocess 自动解码时会在 GBK 环境里把 stderr 解成 None，\n    紧接着 `err.startswith(\"[!]\")` 当场 AttributeError —— 本脚本确实\n    在别的 shell 里这么崩过一次。断言只看 \"[!]\" 这个 ASCII 前缀，\n    所以个别字符被替换掉不影响判定。\n    \"\"\"\n    p = subprocess.run([sys.executable, MINI], input=text,\n                       stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                       encoding=\"utf-8\", errors=\"replace\")\n    return p.stdout or \"\", p.stderr or \"\", p.returncode\n\n\ndef check_e2e():\n    \"\"\"stdout 逐字节比对 + 正常情形 stderr 必须为空。\"\"\"\n    fails = []\n    total = 0\n\n    # (说明, stdin, 期望 stdout)  —— stderr 必须为空\n    clean_cases = [\n        (\"题面样例\", \"3\\n78\\n70906\\n781020569876102789\\n\", \"1\\n0\\n2\\n\"),\n        (\"单组\", \"1\\n5\\n\", \"5\\n\"),\n        (\"T=0（不输出任何东西）\", \"0\\n\", \"\"),\n        (\"空输入\", \"\", \"\"),\n        (\"T 与 n 同行（宽容解析）\", \"2 78 91\\n\", \"1\\n3\\n\"),\n        (\"CRLF 行尾（Windows 文本）\", \"2\\r\\n78\\r\\n91\\r\\n\", \"1\\n3\\n\"),\n        (\"夹空行 / 前后空行\", \"\\n\\n1\\n\\n78\\n\\n\", \"1\\n\"),\n        (\"80 位 + 前导零\", \"2\\n\" + \"1\" + \"0\" * 79 + \"\\n0012\\n\", \"10\\n1\\n\"),\n        (\"每组之间无空行（标准）\", \"4\\n10\\n19\\n91\\n121\\n\", \"10\\n8\\n3\\n0\\n\"),\n        (\"下一行有多余数据（只算 T 组，不再读、不阻塞）\", \"1\\n78\\n99\\n\", \"1\\n\"),\n    ]\n    for why, text, want in clean_cases:\n        total += 1\n        out, err, _rc = run_mini(text)\n        if out != want:\n            fails.append(f\"e2e【{why}】stdout={out!r}, want {want!r}\")\n        if err != \"\":\n            fails.append(f\"e2e【{why}】stderr 应为空，实为 {err!r}\")\n\n    # 非法 / 缺数据：stdout 必须**完全为空**。\n    # 现在答案是读完所有组之后才统一输出的，中途 return 一个字节都不会写出去，\n    # 所以不存在\"打了一半答案\"的情形。stderr 要带 [!] 前缀。\n    bad_cases = [\n        (\"非法 n\", \"1\\nhello\\n\", \"\"),\n        (\"数字混字母\", \"1\\n12abc\\n\", \"\"),\n        (\"带负号（第 2 组才出错，前 1 组也不能漏出去）\", \"2\\n78\\n-91\\n\", \"\"),\n        (\"非法 T\", \"abc\\n78\\n\", \"\"),\n        (\"缺数据（T=3 只给 2 个）\", \"3\\n78\\n91\\n\", \"\"),\n        (\"同一行里多出 token（缓冲区里看得见）\", \"1 78 99\\n\", \"1\\n\"),\n    ]\n    for why, text, want in bad_cases:\n        total += 1\n        out, err, _rc = run_mini(text)\n        if out != want:\n            fails.append(f\"e2e【{why}】stdout={out!r}, want {want!r}\")\n        if not err.startswith(\"[!]\"):\n            fails.append(f\"e2e【{why}】stderr 应以 [!] 开头，实为 {err!r}\")\n\n    return total, fails\n\n\ndef check_streaming(timeout=5.0):\n    \"\"\"铁律 1 的可观测行为：喂完第一组就该立刻出答案，不能等 EOF。\n\n    stdin 故意**不关闭**来模拟终端：若实现用了 sys.stdin.read()，\n    它会一直阻塞到 EOF，这里就会超时拿不到任何输出。\n    \"\"\"\n    p = subprocess.Popen([sys.executable, MINI], stdin=subprocess.PIPE,\n                         stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                         encoding=\"utf-8\", errors=\"replace\")\n    got = []\n\n    def rd():\n        got.append(p.stdout.readline())\n\n    try:\n        p.stdin.write(\"1\\n78\\n\")\n        p.stdin.flush()\n        th = threading.Thread(target=rd)\n        th.daemon = True\n        th.start()\n        th.join(timeout)\n    except Exception as e:                      # noqa: BLE001 - 只为诊断\n        got.append(\"<EXC %s>\" % e)\n    finally:\n        try:\n            p.kill()\n            p.stdin.close()\n            p.stdout.close()\n            p.stderr.close()\n        except Exception:                       # noqa: BLE001\n            pass\n\n    if not got:\n        # 注意：中文串里要引述别的话，用「」而不是 ASCII 双引号 ——\n        # 后者会把 Python 字符串提前截断（与 CLAUDE.md 陷阱 18 同一类坑）\n        return (\"%.0f 秒内没吐出第一行 —— 疑似退回 read()（铁律 1：\"\n                \"终端里表现就是「敲完数据毫无反应」）\" % timeout)\n    if got[0].strip() != \"1\":\n        return \"第一行是 %r，期望 '1'\" % got[0]\n    return None\n\n\ndef check_no_trailing_block(timeout=5.0):\n    \"\"\"收尾不得再读 stdin —— 喂完 T 组后进程必须自己退出。\n\n    修掉之前：读完 T 组还会再取一个 token，终端里表现为\n    「答案已经打完、程序却不结束」，用户以为卡死。\n    这里让 stdin 一直开着来复现终端：进程若在超时内没退出就是复发。\n    \"\"\"\n    p = subprocess.Popen([sys.executable, MINI], stdin=subprocess.PIPE,\n                         stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                         encoding=\"utf-8\", errors=\"replace\")\n    try:\n        p.stdin.write(\"1\\n78\\n\")\n        p.stdin.flush()\n    except Exception as e:                      # noqa: BLE001\n        return \"写入 stdin 失败: %s\" % e\n\n    try:\n        p.wait(timeout=timeout)\n    except subprocess.TimeoutExpired:\n        p.kill()\n        for h in (p.stdin, p.stdout, p.stderr):\n            try:\n                h.close()\n            except Exception:                   # noqa: BLE001\n                pass\n        return (\"喂完 T 组后 %.0f 秒仍未退出 —— 收尾又去读 stdin 了\"\n                \"（终端里就是「打完不结束」）\" % timeout)\n\n    out = p.stdout.read() or \"\"\n    for h in (p.stdin, p.stdout, p.stderr):\n        try:\n            h.close()\n        except Exception:                       # noqa: BLE001\n            pass\n    if out != \"1\\n\":\n        return \"stdout = %r，期望 '1\\\\n'\" % out\n    return None\n\n\ndef check_detailed_e2e(timeout=5.0):\n    \"\"\"详细版也要能自己退出（收尾不阻塞），且末尾标准输出与提交版一致。\n\n    注意这里刻意**不用 communicate()** —— 它会替我们关掉 stdin，\n    那样就测不出\"程序在等 stdin\"这件事了（L1 正是这个毛病）。\n    \"\"\"\n    p = subprocess.Popen([sys.executable, DETAILED], stdin=subprocess.PIPE,\n                         stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n                         encoding=\"utf-8\", errors=\"replace\")\n    try:\n        p.stdin.write(\"2\\n78\\n10\\n\")\n        p.stdin.flush()\n    except Exception as e:                      # noqa: BLE001\n        return \"写入 stdin 失败: %s\" % e\n\n    try:\n        p.wait(timeout=timeout)                 # 输出仅约 3KB，不会撑满管道\n    except subprocess.TimeoutExpired:\n        p.kill()\n        for h in (p.stdin, p.stdout, p.stderr):\n            try:\n                h.close()\n            except Exception:                   # noqa: BLE001\n                pass\n        return \"喂完 T 组后 %.0f 秒仍未退出 —— 收尾又去读 stdin 了\" % timeout\n\n    out = p.stdout.read() or \"\"\n    err = p.stderr.read() or \"\"\n    for h in (p.stdin, p.stdout, p.stderr):\n        try:\n            h.close()\n        except Exception:                       # noqa: BLE001\n            pass\n\n    if err != \"\":\n        return \"stderr 非空: %r\" % err\n    tail = out.rstrip(\"\\n\").split(\"\\n\")[-2:]\n    if tail != [\"1\", \"10\"]:\n        return \"末尾的标准格式输出为 %r，期望 ['1', '10']\" % tail\n    return None\n\n\ndef ast_scan(path):\n    \"\"\"按铁律 5 扫老 OJ 不认的语法，返回 [(说明, 行号)]，空 = 通过。\"\"\"\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        src = f.read()\n    tree = ast.parse(src, path)\n\n    bad = []\n    for node in ast.walk(tree):\n        if isinstance(node, ast.JoinedStr):\n            bad.append((\"f-string\", node.lineno))\n        elif isinstance(node, ast.NamedExpr):\n            bad.append((\"海象运算符 :=\", node.lineno))\n        elif isinstance(node, ast.Nonlocal):\n            bad.append((\"nonlocal\", node.lineno))\n        elif isinstance(node, ast.AnnAssign):\n            bad.append((\"变量类型注解\", node.lineno))\n        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):\n            for a in list(node.args.args) + list(node.args.kwonlyargs):\n                if getattr(a, \"annotation\", None) is not None:\n                    bad.append((\"参数类型注解\", node.lineno))\n            if node.returns is not None:\n                bad.append((\"返回类型注解\", node.lineno))\n        elif isinstance(node, ast.Call):\n            f = node.func\n            if isinstance(f, ast.Name) and f.id == \"input\":\n                bad.append((\"input()\", node.lineno))\n            if isinstance(f, ast.Attribute) and f.attr == \"buffer\":\n                bad.append((\"sys.stdin.buffer\", node.lineno))\n    return bad\n\n\ndef main():\n    rnd = random.Random(20260927)\n    failures = []\n\n    failures += check_anchors()\n\n    exh_total, f = check_exhaustive()\n    failures += f\n\n    rnd_total, f = check_random(rnd)\n    failures += f\n\n    det_total, f = check_detailed(rnd)\n    failures += f\n\n    e2e_total, f = check_e2e()\n    failures += f\n\n    err = check_streaming()\n    if err:\n        failures.append(\"流式（终端行为）: \" + err)\n\n    err = check_no_trailing_block()\n    if err:\n        failures.append(\"收尾不阻塞: \" + err)\n\n    err = check_detailed_e2e()\n    if err:\n        failures.append(\"详细版端到端: \" + err)\n\n    for path in (MINI, DETAILED):\n        for what, lineno in ast_scan(path):\n            failures.append(f\"AST {os.path.basename(path)}:{lineno} 含禁用语法 {what}\")\n\n    if failures:\n        print(\"FAIL: %d 处\" % len(failures))\n        for x in failures[:5]:\n            print(\"  - \" + x)\n        return 1\n\n    # 汇总行用英文：Windows 控制台是 GBK，中文在 `python verify_mod11.py`\n    # 直跑时会变成乱码（CLAUDE.md 陷阱 12）。失败详情保留中文，便于诊断。\n    print(\"OK: anchors %d | exhaustive %d | random %d | detailed 3-way agree %d | \"\n          \"stdout clean %d | streaming ok | no-block ok | detailed e2e ok | \"\n          \"AST clean (2 files)\"\n          % (len(ANCHORS), exh_total, rnd_total, det_total, e2e_total))\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())\n"}];
